// ============================================================
// /api/v1/state-observatory/alerts/evaluate — POST
// ------------------------------------------------------------
// Exposes:
//   - alert-service.evaluateAndRaise (POST, observatory:alert:read)
//
// R3 + E5: deterministic threshold evaluation (no eval). Loads the
// VarianceRecord + Indicator, evaluates alertThresholds (max 2 rules),
// and creates an Alert (lifecycleStage="notified", isAutoGenerated=true)
// if matched. Returns 200 + {alert: null} if no threshold matched
// (R3: no auto-alert). Returns 201 + {alert: Alert} if a new alert
// was raised. Idempotent — re-evaluating an already-notified variance
// record returns the existing alert without creating a duplicate.
// ============================================================
import { NextResponse } from "next/server";
import { evaluateAndRaise } from "@/lib/state-observatory/alert-service";
import { authenticateAndAuthorize, mapServiceError } from "../../_lib";
import { z } from "zod";

export const dynamic = "force-dynamic";

const EvaluateBodySchema = z.object({
  varianceRecordId: z.string().min(1),
});

export async function POST(request: Request) {
  const { session, errorResponse } = await authenticateAndAuthorize(
    "observatory:alert:read"
  );
  if (errorResponse) return errorResponse;

  try {
    const body = await request.json();
    const { varianceRecordId } = EvaluateBodySchema.parse(body);
    const alert = await evaluateAndRaise(session, varianceRecordId);
    if (alert === null) {
      // R3: no thresholds matched → no alert raised. Return 200 with null.
      return NextResponse.json({ alert: null, raised: false }, { status: 200 });
    }
    return NextResponse.json({ alert, raised: true }, { status: 201 });
  } catch (err) {
    return mapServiceError(err);
  }
}
